import type { Client, Workflow } from "@temporalio/client";
import { WorkflowIdConflictPolicy } from "@temporalio/common";

export const startRun = (client: Client, agent: string, thing: string, wf: string | Workflow, ...args: unknown[]) =>
  client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`,
    taskQueue: `ai-agents-${agent}`,
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING,
    args,
  });

const opts = { taskQueue: "ai-agents-nova", workflowId: "nova:RH-1234", args: ["RH-1234"] };
const join = { ...opts, workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING };

